verify:
def skill():
    b = lambda n: n
    a = {}
    for n in range(1, 6):
        F = lambda m: m**2 + 2*m
        c = F(n) - (F(n - 1) if n >= 2 else 0)
        a[n] = c*b(n + 1)
    assert a[1] == 6
    return sum(a.values())

def standard():
    d = Symbol('d')
    dd = solve(Eq(Rational(6)/(1 + d), 3), d)[0]
    b = lambda n: 1 + (n - 1)*dd
    a = [6]
    for n in range(2, 6):
        target = n**2 + 2*n
        prev = sum(a[k - 1]/b(k + 1) for k in range(1, n))
        a.append((target - prev)*b(n + 1))
    return sum(a)

def unique():
    return [standard()]
